"""The hiAnzy knowledge encyclopedia: cornerstone articles.

These sit alongside the shorter editorial notes in seed_data.INSIGHTS and are
served by the same /api/insights routes. The difference is shape, not
plumbing: a knowledge article carries a one-line definition, a topic set from
the controlled vocabulary in frontend/src/data/content.js (INSIGHT_TOPICS),
and an explicit `related` graph the frontend reads to link services,
disciplines, case studies, network rosters and other articles to it.

Body blocks understood by InsightDetail.js:
  p, h2, list, steps, quote, takeaway, faq
Inline links use markdown form and must be site-relative: [label](/path).

Every article here explains a concept the site already sells but never
defined. Nothing below invents customers, results, awards or statistics; the
only proof referenced is the five published case studies, by link.
"""

import re


def _reading_time(body):
    words = 0
    for block in body:
        if block.get("text"):
            words += len(re.findall(r"\w+", block["text"]))
        for item in block.get("items", []) or []:
            if isinstance(item, dict):
                words += len(re.findall(r"\w+", f"{item.get('q', '')} {item.get('a', '')} {item.get('title', '')} {item.get('text', '')}"))
            else:
                words += len(re.findall(r"\w+", str(item)))
    return f"{max(3, round(words / 200))} min"


def _article(**a):
    body = a["body"]
    a.setdefault("format", "knowledge")
    a.setdefault("published", True)
    a.setdefault("readingTime", _reading_time(body))
    a.setdefault("related", {})
    for key in ("services", "disciplines", "work", "network", "insights"):
        a["related"].setdefault(key, [])
    return a


P = lambda text: {"type": "p", "text": text}
H2 = lambda text: {"type": "h2", "text": text}
QUOTE = lambda text: {"type": "quote", "text": text}
TAKEAWAY = lambda text: {"type": "takeaway", "text": text}
LIST = lambda *items: {"type": "list", "items": list(items)}
STEPS = lambda *items: {"type": "steps", "items": [{"title": t, "text": x} for t, x in items]}
FAQ = lambda *items: {"type": "faq", "items": [{"q": q, "a": a} for q, a in items]}


